package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"   // PIC X len=1 = "N"
var WsFirstFlag string = "Y"  // PIC X len=1 = "Y"
var WsPrevDept string = "   " // PIC X(3) len=3 = SPACES
var WsRegHours decimal.Decimal = decimal.NewFromInt(0) // PIC 9(3)V9 len=4 = 0
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)  // PIC 9(3)V9 len=4 = 0
var WsGross decimal.Decimal = decimal.NewFromInt(0)    // PIC 9(7)V99 len=9 = 0
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsDeptCount int64 = 0                                 // PIC 9(3) len=3 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99 len=13 = 0
var WsGrandCount int64 = 0                                // PIC 9(5) len=5 = 0
var WsHoursEd string                                       // PIC ZZ9.9 len=5
var WsRateEd string                                        // PIC ZZ9.99 len=6
var WsGrossEd string                                       // PIC Z,ZZZ,ZZ9.99 len=12
var WsDeptEd string                                        // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsGrandEd string                                       // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var curRec EmpRec
var empLines []string
var empIdx int

func main() {
	mainPara()
}

// helpers

func pow10Int64(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func parseNumField(s string, scale int) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.Zero
	}
	// digits only, may have leading zeros
	d, err := decimal.NewFromString(trimmed)
	if err != nil {
		return decimal.Zero
	}
	return d.Shift(int32(-scale))
}

func padLeftZeros(s string, length int) string {
	if len(s) >= length {
		return s[len(s)-length:]
	}
	return strings.Repeat("0", length-len(s)) + s
}

func storeDecimal(val decimal.Decimal, intDigits, scale int) decimal.Decimal {
	totalDigits := intDigits + scale
	if totalDigits == 0 {
		return decimal.Zero
	}
	scaled := val.Shift(int32(scale)).Truncate(0)
	mod := decimal.NewFromInt(1).Shift(int32(totalDigits))
	if scaled.Sign() < 0 {
		abs := scaled.Abs()
		absMod := abs.Mod(mod)
		return absMod.Neg().Shift(int32(-scale))
	}
	modded := scaled.Mod(mod)
	return modded.Shift(int32(-scale))
}

func storeInt(val int64, digits int) int64 {
	mod := pow10Int64(digits)
	if val < 0 {
		abs := -val
		return -(abs % mod)
	}
	return val % mod
}

func formatUneditedInt(v int64, digits int) string {
	mod := pow10Int64(digits)
	abs := v
	neg := false
	if v < 0 {
		neg = true
		abs = -abs
	}
	val := abs % mod
	s := strconv.FormatInt(val, 10)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	if neg {
		// COBOL would show sign; not needed for this program
		// keep zero padded and prefix minus truncated? just return with minus
		// but to keep width, replace first char with '-'
		if len(s) > 0 {
			s = "-" + s[1:]
		}
	}
	return s
}

func formatEdited(val decimal.Decimal, pic string) string {
	width := len(pic)
	dotIdx := strings.Index(pic, ".")
	// collect positions
	var intPos []int
	var decPos []int
	var commaPos []int
	for i, ch := range pic {
		if ch == 'Z' || ch == '9' {
			if dotIdx == -1 || i < dotIdx {
				intPos = append(intPos, i)
			} else if i > dotIdx {
				decPos = append(decPos, i)
			}
		} else if ch == ',' {
			commaPos = append(commaPos, i)
		}
	}
	intDigits := len(intPos)
	decDigits := len(decPos)

	out := make([]byte, width)
	for i := 0; i < width; i++ {
		out[i] = pic[i]
	}

	// build intStr and fracStr
	var intStr string
	var fracStr string
	if decDigits > 0 {
		shifted := val.Shift(int32(decDigits)).Truncate(0)
		absShifted := shifted.Abs()
		pow10Dec := decimal.NewFromInt(1).Shift(int32(decDigits))
		intPartDec := absShifted.Div(pow10Dec).Truncate(0)
		fracPartDec := absShifted.Mod(pow10Dec)
		if intDigits > 0 {
			modInt := decimal.NewFromInt(1).Shift(int32(intDigits))
			intPartDec = intPartDec.Mod(modInt)
		}
		intStr = padLeftZeros(intPartDec.StringFixed(0), intDigits)
		// StringFixed(0) may return "0" for zero, need to handle "-0" not
		fracStr = padLeftZeros(fracPartDec.StringFixed(0), decDigits)
		// StringFixed may include "-" for negative 0? already abs
	} else {
		absVal := val.Abs().Truncate(0)
		if intDigits > 0 {
			modInt := decimal.NewFromInt(1).Shift(int32(intDigits))
			absVal = absVal.Mod(modInt)
		}
		intStr = padLeftZeros(absVal.StringFixed(0), intDigits)
	}

	// Z suppression
	isDisplayed := make([]bool, len(intPos))
	seenNonZero := false
	for k, pos := range intPos {
		var digit byte
		if k < len(intStr) {
			digit = intStr[k]
		} else {
			digit = '0'
		}
		picChar := pic[pos]
		if picChar == 'Z' && digit == '0' && !seenNonZero {
			out[pos] = ' '
			isDisplayed[k] = false
		} else {
			out[pos] = digit
			isDisplayed[k] = true
			if digit != '0' {
				seenNonZero = true
			}
		}
		if digit != '0' {
			seenNonZero = true
		}
	}
	for k, pos := range decPos {
		var digit byte
		if k < len(fracStr) {
			digit = fracStr[k]
		} else {
			digit = '0'
		}
		out[pos] = digit
	}
	for _, cpos := range commaPos {
		hasLeftDisplayed := false
		for k, p := range intPos {
			if p < cpos && isDisplayed[k] {
				hasLeftDisplayed = true
				break
			}
		}
		if hasLeftDisplayed {
			out[cpos] = ','
		} else {
			out[cpos] = ' '
		}
	}
	return string(out)
}

// paragraphs

func mainPara() {
	// OPEN INPUT EMP-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		empLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// increase buffer for long lines if needed
		const maxCapacity = 1024 * 1024
		buf := make([]byte, maxCapacity)
		scanner.Buffer(buf, maxCapacity)
		for scanner.Scan() {
			line := scanner.Text()
			empLines = append(empLines, line)
		}
		f.Close()
	}
	empIdx = 0
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	if WsFirstFlag != "Y" {
		deptBreakPara()
	}
	// CLOSE EMP-FILE already
	grandPara()
}

func readPara() {
	if empIdx >= len(empLines) {
		WsEofFlag = "Y"
		return
	}
	line := empLines[empIdx]
	empIdx++
	if len(line) < 17 {
		line = line + strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	curRec.ErId = line[0:5]
	curRec.ErDept = line[5:8]
	curRec.ErHours = parseNumField(line[8:12], 1)
	curRec.ErRate = parseNumField(line[12:17], 2)
}

func processPara() {
	if WsFirstFlag == "Y" {
		WsPrevDept = curRec.ErDept
		WsFirstFlag = "N"
	} else {
		if curRec.ErDept != WsPrevDept {
			deptBreakPara()
			WsPrevDept = curRec.ErDept
		}
	}
	payPara()
	readPara()
}

func payPara() {
	if curRec.ErHours.GreaterThan(decimal.NewFromInt(40)) {
		WsRegHours = storeDecimal(decimal.NewFromInt(40), 3, 1)
		diff := curRec.ErHours.Sub(decimal.NewFromInt(40))
		// truncate toward zero to scale 1
		diff = diff.Truncate(1)
		WsOtHours = storeDecimal(diff, 3, 1)
	} else {
		WsRegHours = storeDecimal(curRec.ErHours, 3, 1)
		WsOtHours = storeDecimal(decimal.Zero, 3, 1)
	}
	onePointFive := decimal.NewFromString("1.5")
	term1 := WsRegHours.Mul(curRec.ErRate)
	term2 := WsOtHours.Mul(curRec.ErRate).Mul(onePointFive)
	sum := term1.Add(term2)
	rounded := sum.Round(2)
	WsGross = storeDecimal(rounded, 7, 2)

	WsDeptTotal = storeDecimal(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = storeInt(WsDeptCount+1, 3)
	WsGrandTotal = storeDecimal(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = storeInt(WsGrandCount+1, 5)

	WsHoursEd = formatEdited(curRec.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(curRec.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	line := curRec.ErId + " " + curRec.ErDept + " " + WsHoursEd + " " + WsRateEd + " " + WsGrossEd
	fmt.Fprintln(os.Stdout, line)
}

func deptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsDeptCount, 3)
	line := "  DEPT " + WsPrevDept + " EMPLOYEES: " + countStr + " TOTAL: " + WsDeptEd
	fmt.Fprintln(os.Stdout, line)
	WsDeptTotal = decimal.Zero
	WsDeptCount = 0
}

func grandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsGrandCount, 5)
	line := "GRAND TOTAL (" + countStr + "): " + WsGrandEd
	fmt.Fprintln(os.Stdout, line)
}

